// === FILTER ARTICLES WITH PDFS ===
// Garde seulement les articles ayant un pdf_local OU un pdf_url telechargeable
const items = $input.all();
// UNE REPRISE NE REPORTE PAS LES PHRASES DU RUN PRECEDENT (2026-09-28). La reprise renvoie
// l'article tel que le run d'origine l'a enregistre (src/run_resume.py, `_worker`), phrases
// d'echec comprises, et les nœuds suivants recopient l'article. Mesure du 2026-09-28 par les
// vrais nœuds : une lecture refusee au run 1, puis reussie en reprise, ressortait « ok » avec
// « Lecture du PDF impossible ... ». Les deux phrases sont retirees ICI, a l'entree, pour que
// chacune decrive CE run ; « Summary », qui relit l'entree du workflow, fait de meme.
// LES AUTRES MARQUES D'UN RUN AUSSI (2026-09-29). Refutation du 2026-09-29 par les vrais nœuds :
// une reprise reussie ressortait « ok » avec « never_had_text » (`_extract_reason`).
// RELEVE REFAIT LE 2026-10-06. Methode : dans le code des cinq nœuds de code de ce workflow, les
// affectations `objet._clef =` et les clefs des litteraux de sortie ; une clef construite
// (`o[k] = ...`) echappe a ce releve. Sont retirees ici les clefs relevees qu'un nœud n'ecrit que
// sous condition et qui decrivent le run qui les a posees : la raison et l'erreur d'un article sans
// texte, le modele et le motif d'un modele que le serveur ne sait pas executer, la trace brute
// du modele (cinq premiers articles), la paire de la double extraction et son accord (ecrits
// seulement quand le second appel rend une extraction) et le bloc de la double extraction (ecrit
// seulement quand elle est active). Refutation du 2026-10-06 : une seconde extraction en echec
// laissait la paire d'un run precedent a cote d'une premiere extraction neuve, accord 0 et
// tableau des desaccords compris. NE SONT PAS RETIRES : `screening_model2` et
// `_needs_human_review`, que les workflows du tri sur resume et de la lecture integrale ecrivent
// aussi, ceux du classement et du risque de biais le second (recherche du 2026-10-06 dans
// workflows/), sans que rien sur l'article ne dise quelle etape les a poses ; les indices, les
// champs et la cadence que ce nœud pose sur chaque article retenu ; `_extracted`,
// `_extract_status` et `_extract_source`, que « Parse Extraction » ecrit sur chaque article
// qu'il rend. « Summary » ne reecrit pas `_extract_source` sur l'article qu'il reinjecte (relu le
// 2026-10-06, aucun cas ne l'eprouve).
// LE BADGE « VERIFIE » DE L'EXTRACTION AUSSI (2026-10-16, decision de l'auteur ; cas voisin de
// R5, commit 2831bee). /api/run-articles sert le corpus d'un run d'extraction avec
// `_human_verified` (l'ecran de relecture des donnees extraites le lit par cette route), et ce
// nœud fait extraire CHAQUE article a nouveau : le badge, recopie, restait vrai sur les valeurs
// du modele. L'ecran les cochait et l'index des taches ne demandait plus de les relire ; la
// meta-analyse le lit par la meme regle (`chiffresVerifies`, depuis le tour 3 du lot « meta »), sur
// le corpus que /api/run-articles ou le planificateur lui transmettent deja lu. « Summary » le
// retire aussi de l'article qu'il reinjecte. SEUL CE BADGE PART : `_rob_human_verified` (le risque de biais, separe le meme jour)
// couvre une evaluation que l'extraction ne refait pas, et `_extracted_original` et `_imputed`
// n'arrivent ici par aucun chemin reel (/api/run-articles ne les sert pas ; une reprise renvoie
// l'article du run, que la regle 1 de la fusion garde alors). Cas :
// tests/test_extraction_badge_herite.py.
// LES CHAMPS DE LA CHAINE RELIEE AUSSI (2026-10-17, etape E6). La voie v2 (plus bas) pose sur
// l'article extrait la provenance, l'arbitrage, l'accord, la seconde lecture, le drapeau « a
// relire » et la trace de lecture ; un article qui echoue avant la verification (lecture du PDF,
// modele refuse, arret) n'en recoit aucun, et ceux d'un run precedent restaient a cote de son
// echec, lus par l'ecran de relecture, l'index des taches et le banc comme ceux de CE run. Les
// validations par champ (`_extraction_valide`, posees par la relecture) disaient « validee » des
// valeurs du modele que ce run remplace : elles partent avec le badge, comme a la fusion d'une
// reprise (src/run_resume.py). `extraction_perimetre` est la marque d'un article hors du perimetre
// de CE run (voie v2). `_extracted_original` reste (regle de reprise, voir plus haut).
// `extraction_perimetre_actif` et `extraction_perimetre_etape` (2026-10-17, etape E6, refutation du
// lot) disent le perimetre du run qui les a poses (« Summary ») : ceux d'un run precedent partent.
// Cas : tests/test_extraction_v2_chaine.py.
const _MARQUES_D_UN_RUN = ['_extract_message_fr', '_extract_message_en', '_extract_reason',
  '_extract_error', '_extract_modele', '_extract_motif_serveur', '_debug_llm_raw',
  '_debug_llm_keys', '_extracted_2', '_extraction_field_agreement', '_extraction_agreement',
  '_extraction_double', '_human_verified', '_extracted_prov', '_extracted_prov_2',
  '_extraction_accord', '_extraction_a_relire', '_extraction_arbitrage', '_lecture_extraction',
  '_extraction_valide', 'extraction_perimetre', 'extraction_perimetre_actif',
  'extraction_perimetre_etape'];
const all = items.map(function (i) {
  const a = Object.assign({}, i.json);
  _MARQUES_D_UN_RUN.forEach(function (k) { delete a[k]; });
  return a;
});
// ABSTRACT_FALLBACK_v1 : priorite au PDF ; les articles SANS PDF mais avec un abstract
// exploitable (>= 50 chars) sont extraits depuis l'abstract (Build Prompt gere le repli).
// Seuls les articles sans AUCUN texte (ni PDF ni abstract) sont ecartes.
const MIN_ABS = 50;
// B6_MIXED_NOTEXT_v1 : on trace l'index d'ORIGINE de chaque article retenu, pour pouvoir
// reinjecter dans Summary ceux qui n'ont ni PDF ni abstract exploitable. Sans cela, dans un
// corpus MIXTE, ces articles disparaissaient du XLSX, du .ris, de articles-full.json et du
// comptage PRISMA, sans aucun statut.
const hasText = a => (a.pdf_local && a.pdf_local.length > 0) || ((a.abstract || '').trim().length >= MIN_ABS);
const withPdf = [];
all.forEach((a, i) => { if (hasText(a)) withPdf.push({ ...a, _src_index: i }); });
const extractFields = (all[0] && all[0].extract_fields) || [
  { name: 'population',   description: 'Population studied (age, gender, condition, sample size)' },
  { name: 'intervention', description: 'Intervention or exposure assessed' },
  { name: 'comparator',   description: 'Comparator or control group' },
  { name: 'outcomes',     description: 'Main outcomes measured (with values if available)' },
  { name: 'study_design', description: 'Study design (RCT, cohort, cross-sectional, etc.)' },
  { name: 'period',       description: 'Study period or follow-up duration' },
  { name: 'country',      description: 'Country/region where the study took place' },
  { name: 'main_findings',description: 'Key findings in 2-3 sentences' },
  { name: 'limitations',  description: 'Main limitations reported by the authors' }
];

const nPdf = withPdf.filter(a => a.pdf_local && a.pdf_local.length > 0).length;
console.log('PDF Extract: ' + all.length + ' articles total, ' + withPdf.length + ' exploitables (' + nPdf + ' PDF, ' + (withPdf.length - nPdf) + ' abstract seul)');
console.log('Champs a extraire: ' + extractFields.map(f => f.name).join(', '));

// CADENCE DE LECTURE DES PDF (2026-09-23). Le nœud suivant envoie UNE lecture a la fois et
// attend cet intervalle, lu par une expression sur l'element, avant la suivante (voir plus bas
// pour l'article sans PDF).
//
// DEFAUT MESURE. Le nœud de lecture n'avait aucun groupage : un run reel de 402 references
// ouvrait donc 402 connexions ensemble vers le moteur, dont la file d'ecoute vaut 64.
// Reproduit le 2026-09-23 sur le service du depot lui-meme (route /extract-pdf), 402 lectures
// tirees ensemble : 99 textes, 303 connexions refusees.
//
// LA VALEUR EST MESUREE, PAS DEVINEE (2026-09-23, meme service, 402 lectures, file d'ecoute
// laissee a 64). Huit PDF fabriques reproduisent ce que le run reel annonce pour les fichiers
// de l'auteur (mediane 0,24 s, plage 0,12 a 0,85 s) ; sur ce poste ils coutent 0,235 s en
// mediane et 0,313 s en moyenne. Le nœud n'attend pas ses reponses : sous la MOYENNE, les
// lectures s'accumulent.
//     une lecture toutes les 250 ms   395 textes, 7 refus, jusqu'a 74 lectures en attente ;
//     une lecture toutes les 350 ms   402 textes, 0 refus, 3 lectures en attente au plus.
// Meme banc, chaque lecture coutant deux fois plus (moyenne 0,609 s) : 500 ms perd 9 lectures,
// 700 ms rend les 402. D'ou 700 ms, pour un cout de 402 x 0,7 s, soit 281,8 s mesurees.
const CADENCE_LECTURE_PDF_MS = 700;

// LA CADENCE DES APPELS AU MODELE SUIT LE PREMIER ELEMENT EMIS (2026-10-17, etape E6, banc du lot).
// Le routeur de modules (« Prepare Articles », workflows/ultralab-module.json) ne pose `_pacing_ms`
// que sur le PREMIER article du corpus, et « Build Prompt » la relit sur le premier element que ce
// nœud lui transmet. CE QUI ETAIT FAUX, MESURE par le banc : premier article hors du perimetre
// « inclus » (voie v2) ou sans aucun texte (voies v1 et v2, deja vrai sur la base 158c798), chaque
// appel partait avec un intervalle de 0 ms au lieu de 4 000 ms ; or le nœud d'appel n'attend pas
// ses reponses (src/cadence.py) : tous partaient ensemble, et la porte du relais les faisait
// attendre au-dela du delai de 420 s du nœud. Le premier enregistrement d'un corpus est souvent un
// exclu. CE QUI CHANGE : la cadence du premier article RECU est posee sur le premier element emis,
// dans les deux voies ; un corpus qui n'en porte pas n'en recoit pas (« Build Prompt », voie v2,
// distingue alors l'absence d'un zero mesure).
const __cadence = Object.prototype.hasOwnProperty.call(all[0] || {}, '_pacing_ms')
  ? { _pacing_ms: all[0]._pacing_ms } : {};

// =============================================================================================
// LA CHAINE D'EXTRACTION RELIEE (voie v2, 2026-10-17, etape E6, brique 13 de la conception).
// =============================================================================================
// CE QUI ETAIT FAUX. La voie v1 (plus bas, gardee pour le banc d'exactitude) extrait tout le
// corpus recu, exclus de la lecture integrale compris, n'envoie au modele que les 12 000 premiers
// caracteres de chaque article en un seul appel, et n'estime aucune duree : un run de plusieurs
// centaines de references pouvait atteindre le plafond de 24 h de l'execution
// (docker/docker-compose.yml, EXECUTIONS_TIMEOUT) sans que rien l'annonce. Les routes du plan
// (/extraction/plan-run, /extraction/plan), de la double extraction (/extraction/double,
// /extraction/ordre), des figures et de la verification (/extraction/verify) existaient dans le
// relais, et aucun nœud ne les appelait.
// CE QUI CHANGE, dans ce nœud. Le reglage cache `extraction_pipeline` (src/settings.py) choisit la
// voie : « v1 » ecrit tel quel rend l'ancienne, toute autre valeur (le defaut « v2 », un reglage
// absent ou illisible) la nouvelle. Puis, dans cet ordre :
//   1. le perimetre « inclus » (POST /extraction/perimetre, la regle UNIQUE du produit, celle du
//      risque de biais), propose par defaut : `extraction_inclus_seulement` faux sur le premier
//      article fait extraire tout le corpus. Un article hors du perimetre n'est ni lu ni extrait :
//      il ressort TEL QU'IL EST ARRIVE (« Summary », « No PDF Passthrough »), marque
//      `extraction_perimetre: 'hors'` ;
//   2. la sonde du modele, inchangee ;
//   3. la double extraction (POST /extraction/double), dite dans le journal du run ;
//   4. le plan du run (POST /extraction/plan-run) : palier de chaque article par passe, duree
//      estimee et decoupage au-dela de son seuil, dits dans le journal du run. Le premier element
//      emis porte ce qu'en lisent les nœuds suivants (`_v2`).
// Une route qui ne repond pas n'arrete rien et se dit : perimetre illisible, tout le corpus est
// extrait ; double extraction illisible, une seule lecture ; plan du run illisible, aucune
// estimation (chaque article est encore planifie par « Build Prompt »).
// Cas : tests/test_extraction_v2_chaine.py.
let __cfgEx = {};
try { __cfgEx = await this.helpers.httpRequest({ method: 'GET', url: 'http://host.docker.internal:8080/api/config', timeout: 5000, json: true }) || {}; } catch (e) { __cfgEx = {}; }
if (__cfgEx.extraction_pipeline !== 'v1') {
  const __RELAIS = 'http://host.docker.internal:3456';
  const __a0 = all[0] || {};
  const __module = String(__a0._module_mode || 'extraction');
  const __dire = function (fr, en) { console.log('[Extraction] ' + fr); console.log('[Extraction] ' + en); };
  const __poster = async (route, corps, delai) => {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: __RELAIS + route,
        headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corps), json: true,
        timeout: delai, returnFullResponse: true, ignoreHttpStatusErrors: true });
      const c = r && r.body;
      return { statut: Number(r && r.statusCode) || 0, corps: (c && typeof c === 'object') ? c : {} };
    } catch (e) {
      return { statut: 0, corps: {}, erreur: String((e && e.message) || e).substring(0, 200) };
    }
  };
  // Le motif d'une route qui n'a pas repondu comme convenu, dans chaque langue.
  const __motif = function (r, langue) {
    const m = r.corps[langue === 'fr' ? 'message_fr' : 'message_en'];
    const s = (typeof m === 'string' && m) ? m : (r.erreur || ((langue === 'fr' ? 'statut ' : 'status ') + r.statut));
    return String(s).replace(/[.\s]+$/, '');
  };
  const __duree = function (s) {
    s = Math.max(0, Math.round(Number(s) || 0));
    if (s < 60) return s + ' s';
    const m = Math.round(s / 60);
    if (m < 60) return m + ' min';
    const h = Math.floor(m / 60), r = m % 60;
    return h + ' h ' + (r < 10 ? '0' : '') + r + ' min';
  };

  // 1. LE PERIMETRE « INCLUS ».
  // LE PERIMETRE DU RUN EST ECRIT SUR SES ARTICLES (2026-10-17, refutation du lot). CE QUI ETAIT
  // FAUX : la porte et l'etape qui avait tranche n'etaient dites que dans la console de ce nœud, que
  // rien ne relit ; un corpus trie sur le resume seul (porte fermee : tout extrait, exclusions du tri
  // comprises) ne laissait aucune trace dans les statistiques, le rapport ni le corpus du run. CE QUI
  // CHANGE : `__perim` {actif, etape}, que « Summary » pose sur chaque article rendu
  // (`extraction_perimetre_actif`, `extraction_perimetre_etape`, sans tiret bas pour traverser le
  // chargeur du planificateur, comme `rob_perimetre_actif`) et qu'« Assemble Results » publie.
  // `etape` : celle de la route (texte_integral, resume, aucune), « tout_le_corpus » quand le filtre
  // est retire, « illisible » quand la route n'a pas repondu comme convenu.
  let __dans = all.map(function () { return true; });
  let __perim = { actif: false, etape: 'tout_le_corpus' };
  if (__a0.extraction_inclus_seulement === false) {
    __dire('Extraction de tout le corpus demandée : ' + (all.length === 1 ? "l'unique article reçu est extrait"
      : 'les ' + all.length + ' articles reçus sont extraits') + ', exclus de la lecture intégrale compris.',
      'Extraction of the whole corpus requested: ' + (all.length === 1 ? 'the only record received is extracted'
      : 'all ' + all.length + ' records received are extracted') + ', full-text exclusions included.');
  } else {
    const p = await __poster('/extraction/perimetre', { articles: all }, 60000);
    if (p.statut === 200 && Array.isArray(p.corps.dans) && p.corps.dans.length === all.length) {
      __dans = p.corps.dans.map(function (x) { return x === true; });
      __perim = { actif: p.corps.applique, etape: p.corps.etape };
      __dire(String(p.corps.message_fr || ''), String(p.corps.message_en || ''));
    } else {
      // Une reponse 200 dont la liste ne compte pas un booleen par article n'est pas lue : sa phrase
      // decrirait un autre decoupage que celui du run.
      const n = (p.statut === 200 && Array.isArray(p.corps.dans)) ? p.corps.dans.length : null;
      const mfr = (n === null) ? __motif(p, 'fr') : ('réponse incomplète du relais : ' + n + ' décision(s) pour ' + all.length + ' article(s)');
      const men = (n === null) ? __motif(p, 'en') : ('incomplete answer from the relay: ' + n + ' decision(s) for ' + all.length + ' record(s)');
      __perim = { actif: false, etape: 'illisible' };
      __dire("Le périmètre « inclus » n'a pas pu être lu (" + mfr + ') : tout le corpus est extrait.',
        'The "included" scope could not be read (' + men + '): the whole corpus is extracted.');
    }
  }
  const __hors = [];
  __dans.forEach(function (d, i) { if (!d) __hors.push(i); });
  // L'article hors du perimetre ressort TEL QU'IL EST ARRIVE, marques comprises, comme le risque de
  // biais rend les siens : son extraction precedente n'est ni refaite ni effacee. Son index d'origine
  // (`_src_index`) le fait reconnaitre par « Summary », qui sinon le reinjecterait « sans texte ».
  const __corpus = all.map(function (a, i) {
    return __dans[i] ? a : Object.assign({}, items[i].json, { extraction_perimetre: 'hors', _src_index: i });
  });
  const __candidats = withPdf.filter(function (a) { return __dans[a._src_index]; });
  // Les deux chemins sans appel ci-dessous portent eux aussi le perimetre (`_v2`), que « Summary »
  // pose sur chaque article rendu.
  if (__candidats.length === 0) {
    return [{ json: { _error: 'Aucun texte exploitable (ni PDF ni abstract >= 50 chars). Lancez pdf-fetch ou recuperez les abstracts.', _no_pdf_passthrough: true, _articles: __corpus,
      _v2: { hors: __hors, perimetre: __perim } } }];
  }

  // 2. LA SONDE DU MODELE, comme la voie v1 (plus bas).
  const __refus = await _sonderModele.call(this, 'extraction');
  if (__refus) {
    const _fr = String(__refus.message_fr || '');
    const _en = String(__refus.message_en || '');
    console.log('[Extraction] ' + _fr);
    console.log('[Extraction] ' + _en);
    return [{ json: { _no_pdf_passthrough: true,
      _modele_inexecutable: { message_fr: _fr, message_en: _en,
        modele: String(__refus.model || ''), motif: String(__refus.motif_serveur || '') },
      _articles: __corpus.map(function (a, i) {
        return __dans[i] ? Object.assign({}, a, { _src_index: i, _a_du_texte: !!hasText(a) }) : a;
      }), _v2: { hors: __hors, perimetre: __perim } } }];
  }

  // 3. LA DOUBLE EXTRACTION. Le relais ne lit pas le corps : tout vient des reglages.
  let __double = null;
  const d2 = await __poster('/extraction/double', {}, 60000);
  if (d2.statut === 200 && d2.corps.success === true) {
    __double = { double: d2.corps.double === true, modele_1: d2.corps.modele_1, modele_2: d2.corps.modele_2 };
    __dire(String(d2.corps.message_fr || ''), String(d2.corps.message_en || ''));
  } else {
    __dire("La double extraction n'a pas pu être résolue (" + __motif(d2, 'fr') + ') : une seule lecture, par le modèle d\'extraction.',
      'The double extraction could not be resolved (' + __motif(d2, 'en') + '): a single reading, by the extraction model.');
  }
  // LE SECOND MODELE EST SONDE AUSSI (2026-10-17, refutation du lot). CE QUI ETAIT FAUX : seul le
  // modele 1 l'etait, et /extraction/double ne lit que /api/show, sans lancer le modele. MESURE de la
  // refutation (serveur qui ne sait pas executer « modele-b », trois articles) : les six appels de la
  // passe 2 etaient emis, et chacun rendait 502, envoye trois fois par le nœud d'appel (retryOnFail)
  // ; la voie v1 cessait des le premier refus. CE QUI CHANGE : la meme sonde, etiquetee
  // `extraction_pass2` (le relais y resout le second modele, ne la compte ni dans la barre ni dans le
  // releve des reglages). Un refus « modele inexecutable » se dit une fois ici ; la seconde passe
  // n'est ni planifiee ni emise (`refus_2`), et le bloc de la double extraction compte chaque
  // article sans seconde lecture (« Parse Extraction », `n_sans_seconde_extraction`).
  if (__double && __double.double) {
    const r2 = await _sonderModele.call(this, 'extraction_pass2');
    if (r2) {
      __double.refus_2 = { message_fr: String(r2.message_fr || ''), message_en: String(r2.message_en || '') };
      console.log('[Extraction double] ' + __double.refus_2.message_fr + " Aucune seconde lecture ne part : chaque article n'est lu qu'une fois.");
      console.log('[Extraction double] ' + __double.refus_2.message_en + ' No second reading is sent: each record is read once.');
    }
  }
  const __passe2 = !!(__double && __double.double && !__double.refus_2);

  // 4. LE PLAN DU RUN.
  const pr = await __poster('/extraction/plan-run', { articles: __candidats, champs: extractFields,
    question: __a0.question, critere: __a0.extraction_critere, cible: __a0.extraction_cible,
    passes: __passe2 ? [1, 2] : [1], _ultralab_module: __module }, 1800000);
  let __plan = null;
  if (pr.statut === 200 && pr.corps.success === true && Array.isArray(pr.corps.articles)) {
    __plan = { articles: pr.corps.articles, par_passe: Array.isArray(pr.corps.par_passe) ? pr.corps.par_passe : null };
    const de = pr.corps.duree_estimee_s || {};
    const src = { modele: ['débits mesurés pour ce modèle', 'throughput measured for this model'],
      profil: ['débits mesurés du profil de calcul', 'measured throughput of the computing profile'],
      non_mesure: ['débits non mesurés sur ce poste : fourchette large', 'throughput not measured on this computer: wide range'] }[de.source_debits] || ['débits inconnus', 'unknown throughput'];
    __dire('Durée estimée des appels au modèle : de ' + __duree(de.bas) + ' à ' + __duree(de.haut) + ' (' + src[0] + ').',
      'Estimated duration of the model calls: from ' + __duree(de.bas) + ' to ' + __duree(de.haut) + ' (' + src[1] + ').');
    const dc = pr.corps.decoupage || {};
    const seuil = Math.round((Number(dc.seuil_s) || 0) / 3600), plafond = Math.round((Number(dc.plafond_s) || 0) / 3600);
    if (dc.propose === true) {
      __dire('Au-delà de ' + seuil + ' h : découper ce run en ' + dc.lots + ' lots est conseillé, car une exécution est arrêtée à ' + plafond + ' h.',
        'Beyond ' + seuil + ' h: splitting this run into ' + dc.lots + ' batches is advised, as an execution is stopped at ' + plafond + ' h.');
    } else if (dc.propose === null) {
      __dire('La durée pourrait dépasser ' + seuil + ' h (débits non mesurés sur ce poste) : découper ce run en ' + dc.lots + ' lots reste prudent, car une exécution est arrêtée à ' + plafond + ' h.',
        'The duration could exceed ' + seuil + ' h (throughput not measured on this computer): splitting this run into ' + dc.lots + ' batches remains prudent, as an execution is stopped at ' + plafond + ' h.');
    }
    const cf = pr.corps.champs_fusionnes;
    if (cf && typeof cf.message_fr === 'string') __dire(cf.message_fr, String(cf.message_en || ''));
  } else if (pr.corps.ultralab_cancelled === true) {
    __dire("Arrêt du run demandé pendant le plan : aucune estimation de durée.",
      'Run stop requested during the plan: no duration estimate.');
  } else {
