// Les comptes du journal ne portent que sur les articles de CE run : un article hors du perimetre
// (voie v2) garde le statut d'une extraction precedente, qui n'est pas un resultat de ce run.
const _compte = articles.filter(a => a.extraction_perimetre !== 'hors');
const ok = _compte.filter(a => a._extract_status === 'ok').length;
const parseErr = _compte.filter(a => a._extract_status === 'parse_error').length;
const llmErr = _compte.filter(a => a._extract_status === 'llm_error').length;
const noText = _compte.filter(a => a._extract_status === 'no_text_available').length;
const jamaisDeTexte = _compte.filter(a => a._extract_reason === 'never_had_text').length;
// LES ECHECS SE COMPTENT PAR STATUT (2026-09-23), tous ceux qui sont presents, au lieu de
// quatre compteurs choisis d'avance : un refus de connexion range sous « sans texte » est
// exactement ce qui a fait croire que 335 references sur 402 n'avaient pas de texte.
const parStatut = {};
_compte.forEach(function (a) {
  const s = String(a._extract_status || '(aucun)');
  parStatut[s] = (parStatut[s] || 0) + 1;
});
const failed = _compte.length - ok;
console.log('=== PDF Extract complete ===');
console.log('Articles traites : ' + _compte.length);
console.log('  OK              : ' + ok);
console.log('  Erreurs parse   : ' + parseErr);
console.log('  Erreurs LLM     : ' + llmErr);
console.log('  Sans texte      : ' + noText + ' (dont ' + jamaisDeTexte + ' sans PDF ni abstract)');
console.log('  Par statut      : ' + JSON.stringify(parStatut));
console.log('  By status     : ' + JSON.stringify(parStatut));
// Une phrase par statut en echec, dite UNE fois : celle du premier article qui le porte.
Object.keys(parStatut).forEach(function (s) {
  if (s === 'ok') return;
  const a = _compte.filter(function (x) { return String(x._extract_status || '(aucun)') === s; })[0] || {};
  if (a._extract_message_fr) console.log('  [' + s + '] ' + a._extract_message_fr);
  if (a._extract_message_en) console.log('  [' + s + '] ' + a._extract_message_en);
});
if (failed === _compte.length) {
  console.log('!!! AUCUN article extrait avec succes - verifier que :');
  console.log('  1. Les PDFs sont bien presents (champ pdf_local rempli)');
  console.log('  2. Le proxy /extract-pdf fonctionne (logs proxy)');
  console.log('  3. Le LLM repond bien (logs proxy /api/generate)');
  // Logger le 1er article en detail pour debug
  const a = articles[0] || {};
  console.log('  Article 0 :');
  console.log('    pdf_local : ' + (a.pdf_local || '(vide)'));
  console.log('    status    : ' + a._extract_status);
  console.log('    source    : ' + a._extract_source);
  console.log('    extracted : ' + JSON.stringify(a._extracted || {}));
}
return articles.map(a => ({ json: a }));

// B6_NO_PDF_SUMMARY_v1 - corpus sans aucun PDF : on saute l'extraction PDF + LLM
// et on renvoie les articles marques no_pdf pour qu'Assemble Results ecrive un summary propre (extracted=0).
const it = $input.all()[0].json;
const arts = (it._articles || []);
// L'ARTICLE HORS DU PERIMETRE DE L'EXTRACTION RESSORT TEL QUEL (voie v2, 2026-10-17, etape E6) :
// « Filter & Prepare » le rend tel qu'il est arrive, marque `extraction_perimetre: 'hors'` ; il n'a
// ete ni lu ni extrait, et aucun statut de CE run ne le decrit. Il garde sa place dans le corpus.
const hors = function (a) { return a.extraction_perimetre === 'hors'; };
const nHors = arts.filter(hors).length;
// LE MODELE QUE LE SERVEUR NE SAIT PAS EXECUTER PREND LE MEME CHEMIN (2026-09-23). La sonde
// du nœud « Filter & Prepare » l'a vu avant toute lecture : aucun PDF n'est lu, aucun appel
// ne part, et chaque article ressort avec un statut qui dit pourquoi. Celui qui n'avait de
// toute facon aucun texte garde « no_text_available » : le modele n'y est pour rien.
if (it._modele_inexecutable) {
  const m = it._modele_inexecutable;
  console.log('[PDF Extract] modele inexecutable : ' + (arts.length - nHors) + ' article(s) non extraits, aucun PDF lu, aucun appel d\'extraction envoye apres la sonde.');
  console.log('[PDF Extract] model cannot run: ' + (arts.length - nHors) + ' article(s) not extracted, no PDF read, no extraction call sent after the check.');
  return arts.map(function (a) {
    if (hors(a)) return { json: a };
    const o = Object.assign({}, a, { _extracted: {}, _extract_source: 'none' });
    delete o._a_du_texte;
    if (a._a_du_texte) {
      o._extract_status = 'model_cannot_run';
      o._extract_message_fr = String(m.message_fr || '');
      o._extract_message_en = String(m.message_en || '');
      o._extract_modele = String(m.modele || '');
      o._extract_motif_serveur = String(m.motif || '');
    } else {
      o._extract_status = 'no_text_available';
      o._extract_reason = 'never_had_text';
    }
    return { json: o };
  });
}
console.log('[PDF Extract] B6 : aucun PDF dans le corpus (' + (arts.length - nHors) + ' articles) -> summary extracted=0');
if (!arts.length) return [{ json: { _extract_status: 'no_pdf', _extracted: {}, title: '(corpus vide)' } }];
return arts.map(function (a) { return hors(a) ? { json: a } : { json: Object.assign({}, a, { _extract_status: 'no_pdf', _extracted: {}, _extract_error: 'Ni PDF ni abstract exploitable - lancer pdf-fetch ou recuperer les abstracts' }) }; });
